const tabId = 118779795;

const collectedPosts = await browserjs(tabId, async () => {
  const seen = new Map();

  async function collectVisible() {
    const articles = document.querySelectorAll('article');
    for (const art of articles) {
      const linkEl = art.querySelector('a[href*="/gag/"]');
      if (!linkEl) continue;
      const url = linkEl.href;
      const id = url.split('/gag/')[1]?.split('?')[0];
      if (!id || seen.has(id)) continue;

      const titleEl = art.querySelector('h2, h1, header a.badge-track');
      const title = titleEl ? titleEl.textContent.trim() : '';

      const lines = art.innerText.split('\n').map(s => s.trim()).filter(Boolean);

      // Extract upvotes and comments
      // Look for lines like "56K", "42K", "37K" followed by comments count
      let upvotes = '';
      let comments = '';
      let section = lines[0] || '';
      let date = lines[1] || '';

      // find index of "Comments"
      const commentsIdx = lines.indexOf('Comments');
      if (commentsIdx > 0) {
        comments = lines[commentsIdx - 1];
        if (commentsIdx - 2 >= 0) {
          upvotes = lines[commentsIdx - 2];
        }
      }

      seen.set(id, {
        id,
        title,
        url,
        section,
        date,
        upvotes,
        comments,
        lines: lines.slice(0, 10)
      });
    }
  }

  // Start at top
  window.scrollTo(0, 0);
  await new Promise(r => setTimeout(r, 800));
  await collectVisible();

  // Scroll down incrementally
  for (let i = 0; i < 6; i++) {
    window.scrollBy(0, 800);
    await new Promise(r => setTimeout(r, 800));
    await collectVisible();
  }

  return Array.from(seen.values());
});

console.log(`Collected ${collectedPosts.length} posts:`);
